package com.zeptopluse.controller; import com.zeptopluse.dto.*; import com.zeptopluse.service.CustomerService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/customers") @RequiredArgsConstructor public class CustomerController { private final CustomerService service; @PostMapping public ResponseEntity<CustomerResponse> create(@Valid @RequestBody CustomerRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request));} @GetMapping("/{id}") public CustomerResponse get(@PathVariable Long id){return service.get(id);} }